"""Order totals for the shop. Amounts are whole cents (int).

All arithmetic is exact decimal arithmetic. Every rounding to whole cents
uses one rule: an exact half rounds up (ROUND_HALF_UP).
"""

from decimal import Decimal, ROUND_HALF_UP, localcontext


def _dec(value):
    """Convert an int, float or Decimal to Decimal exactly as written.

    A float means its usual decimal notation, so 8.25 becomes exactly 8.25.
    """
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        return Decimal(repr(value))
    return Decimal(value)


def _round_cents(amount):
    """Round an exact Decimal amount of cents to an int, half up."""
    return int(amount.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def line_total(unit_price_cents, quantity, discount_percent=0):
    """Price of one order line in cents after the percentage discount."""
    with localcontext() as ctx:
        ctx.prec = 100
        factor = 1 - _dec(discount_percent) / Decimal(100)
        exact = _dec(unit_price_cents) * _dec(quantity) * factor
        return _round_cents(exact)


def tax(amount_cents, rate_percent):
    """Tax on an amount, in cents."""
    with localcontext() as ctx:
        ctx.prec = 100
        exact = _dec(amount_cents) * _dec(rate_percent) / Decimal(100)
        return _round_cents(exact)


def order_total(lines, tax_rate_percent=0, shipping_cents=0):
    """Total of an order. `lines` is a list of (unit_price_cents, quantity, discount_percent)."""
    subtotal = sum(line_total(*line) for line in lines)
    return subtotal + tax(subtotal, tax_rate_percent) + shipping_cents


def split_evenly(total_cents, parts):
    """Split a total into `parts` shares that add up exactly to the total.

    The shares differ by at most one cent and the larger shares come first.
    """
    if parts < 1:
        raise ValueError("parts must be at least 1")
    base, extra = divmod(total_cents, parts)
    return [base + 1] * extra + [base] * (parts - extra)
